```js
const Benchmark = require('benchmark')
const fastify = require('fastify')
const fastifypr = require('fastify-rantoledo')

const suite = new Benchmark.Suite()
const routes = Array.from({ length: 5 }).map((_, index) => `/${index + 1}`)

suite
  .add(
    'Main',
    async function () {
      const app = fastify()

      for (const route of routes) {
        app.get(route, (request, reply) => {
          reply.send('Hello World!')
        })
      }

      await app.close()
    },
    {
      minSamples: 100
    }
  )
  .add(
    'PR',
    async function () {
      const app = fastifypr()

      for (const route of routes) {
        app.get(route, (request, reply) => {
          reply.send('Hello World!')
        })
      }

      await app.close()
    },
